 103	 .pageIndex(searchProfileRequest.getPageIndex())
 104	 .totalElements(totalProfiles)
 105	 .totalPages((int) (Math.ceil((double) totalProfiles / searchProfileRequest.getPageSize())))
 106	 .hasNext(searchProfileRequest.getPageIndex() + searchProfileRequest.getPageSize() < totalProfiles)
 107	 .hasPrevious(searchProfileRequest.getPageIndex() > 1)
 108	 .build();
 109	
 110	 return PageApiResponse.<List<ProfileDTO>>builder()
